import sys, numpy as np
sys.path.insert(0,'/workspace/task/source'); sys.path.insert(0,'/tmp')
from proto import metric
from Pynite import FEModel3D, Analysis

def mk():
    m = FEModel3D(); m.add_material('steel',29000,11200,0.3,0.284); m.add_section('S',10,100,150,250); return m

def reduced(model):
    Analysis._prepare_model(model)
    D1,_,_ = Analysis._partition_D(model)
    Kd = model.Ke('Combo 1', False, False, False)
    return Kd[np.ix_(D1,D1)]

def report(name, model, expect):
    K11 = reduced(model)
    if K11.shape[0]==0:
        print(f'{name:42s} EMPTY'); return
    md,_ = metric(K11, False); ms,_ = metric(K11, True)
    print(f'{expect:8s} {name:42s} n={K11.shape[0]:5d} dense={md:11.3e} sparse={ms:11.3e}')

models = []
def add(name, fn, expect): models.append((name, fn, expect))

# ---------------- UNSTABLE ----------------
def u_free_node():
    m=mk(); m.add_node('a',0,0,0); m.add_node('b',10,0,0); m.add_node('c',20,5,0)
    m.add_member('m','a','b','steel','S'); m.def_support('a',1,1,1,1,1,1); return m
add('free floating node', u_free_node, 'UNSTBL')

def u_planar_frame_no_z():
    # planar frame in XY, all members in plane, no out-of-plane restraint at supports for RX? still stable
    m=mk()
    m.add_node('a',0,0,0); m.add_node('b',0,10,0); m.add_node('c',12,10,0); m.add_node('d',12,0,0)
    for nm,(i,j) in {'1':('a','b'),'2':('b','c'),'3':('c','d')}.items(): m.add_member(nm,i,j,'steel','S')
    m.def_support('a',1,1,1,0,0,0); m.def_support('d',1,1,1,0,0,0)   # pinned bases, rotations free
    return m
add('planar frame pinned bases (stable)', u_planar_frame_no_z, 'STABLE')

def u_two_pin_supports_line():
    # like case_a but bigger: 6-node ring rotating about line of two pins
    m=mk()
    pts = [(0,0,0),(5,1,2),(9,6,1),(6,10,3),(1,8,2),(-2,4,1)]
    for i,(x,y,z) in enumerate(pts): m.add_node(f'n{i}',x,y,z)
    for i in range(6): m.add_member(f'm{i}', f'n{i}', f'n{(i+1)%6}','steel','S')
    m.def_support('n0',1,1,1,0,0,0)
    m.def_support('n1',0,1,1,0,0,0)   # rotation about n0-n1 axis unrestrained... n1 restrained DY,DZ
    return m
add('ring w/ 2 supports (rigid rotation)', u_two_pin_supports_line, 'UNSTBL')

def u_torsion_chain(N=200):
    m=mk()
    for i in range(N+1): m.add_node(f'n{i}', i*1.0,0,0)
    for i in range(N): m.add_member(f'm{i}',f'n{i}',f'n{i+1}','steel','S')
    m.def_support('n0',1,1,1,0,1,1)
    return m
add('200-elem chain, torsion free', u_torsion_chain, 'UNSTBL')

def u_hinge_mech():
    m=mk(); m.add_node('a',0,0,0); m.add_node('b',5,0,0); m.add_node('c',10,0,0)
    m.add_member('m1','a','b','steel','S'); m.add_member('m2','b','c','steel','S')
    m.def_support('a',1,1,1,1,1,1); m.def_support('c',1,1,1,1,1,1)
    m.def_releases('m1',False,False,False,False,False,True, False,False,False,False,False,True)
    m.def_releases('m2',False,False,False,False,False,True, False,False,False,False,False,True)
    return m
add('beam with RZ hinges (mechanism)', u_hinge_mech, 'UNSTBL')

def u_truss_mech():
    # 4-bar "square" truss with pinned ends -> in-plane mechanism (needs diagonal)
    m=mk()
    for nm,(x,y) in {'a':(0,0),'b':(10,0),'c':(10,10),'d':(0,10)}.items(): m.add_node(nm,x,y,0)
    for nm,(i,j) in {'1':('a','b'),'2':('b','c'),'3':('c','d'),'4':('d','a')}.items():
        m.add_member(nm,i,j,'steel','S')
        m.def_releases(nm, False,False,False,True,True,True, False,False,False,True,True,True)
    m.def_support('a',1,1,1,0,0,0); m.def_support('b',0,1,1,0,0,0)
    for n in ('a','b','c','d'): m.def_support(n, None, None, 1, 1, 1, 1) if False else None
    for n in ('c','d'): m.def_support(n,0,0,1,1,1,1)
    m.def_support('a',1,1,1,1,1,1); m.def_support('b',0,1,1,1,1,1)
    return m
add('4-bar truss square (mechanism)', u_truss_mech, 'UNSTBL')

def u_case_a(scale=1.0, E=29000):
    m=FEModel3D(); m.add_material('steel',E,E*0.386,0.3,0.284); m.add_section('S',10,100,150,250)
    for name,x,y,z in (("p",0,0,0),("q",6,1,2),("r",2,7,0.5)): m.add_node(name,x*scale,y*scale,z*scale)
    for name,i,j in (("e1","p","q"),("e2","q","r"),("e3","r","p")): m.add_member(name,i,j,'steel','S')
    m.def_support("p",1,1,1,0,0,0); m.def_support("q",0,1,1,0,0,0)
    return m
add('case_a', lambda: u_case_a(), 'UNSTBL')
add('case_a x1000 scale', lambda: u_case_a(1000.0), 'UNSTBL')
add('case_a E=1e9', lambda: u_case_a(1.0, 1e9), 'UNSTBL')
add('case_a scale 0.001', lambda: u_case_a(0.001), 'UNSTBL')

def u_plate_mesh_pin():
    m=mk(); m.add_material('c',3600,1500,0.2,0.0868)
    m.add_rectangle_mesh('M',1.0,12,12,0.5,'c',1,1,[0,0,0],'XY'); m.meshes['M'].generate()
    for node in list(m.nodes.values()):
        if abs(node.Y)<1e-9: m.def_support(node.name,1,1,1,0,0,0)
    return m
add('plate mesh pinned edge', u_plate_mesh_pin, 'UNSTBL')

# ---------------- STABLE ----------------
def s_control():
    m=mk(); m.add_node('n1',0,0,0); m.add_node('n2',10,0,0); m.add_member('m','n1','n2','steel','S')
    m.def_support('n1',1,1,1,1,1,1); m.def_support('n2',0,1,1,0,0,0); return m
add('control beam', s_control,'STABLE')

def s_chain(N):
    def f():
        m=mk()
        for i in range(N+1): m.add_node(f'n{i}', i*1.0,0,0)
        for i in range(N): m.add_member(f'm{i}',f'n{i}',f'n{i+1}','steel','S')
        m.def_support('n0',1,1,1,1,1,1)
        return m
    return f
for N in (10,50,200,600):
    add(f'{N}-elem cantilever chain', s_chain(N), 'STABLE')

def s_slender_chain():
    # very slender: tiny I, long length
    m=FEModel3D(); m.add_material('s',29000,11200,0.3,0.284); m.add_section('S',0.5,0.01,0.01,0.005)
    N=400
    for i in range(N+1): m.add_node(f'n{i}', i*5.0,0,0)
    for i in range(N): m.add_member(f'm{i}',f'n{i}',f'n{i+1}','s','S')
    m.def_support('n0',1,1,1,1,1,1)
    return m
add('400-elem very slender chain', s_slender_chain, 'STABLE')

def s_plate_fixed(nx=20):
    def f():
        m=mk(); m.add_material('c',3600,1500,0.2,0.0868)
        m.add_rectangle_mesh('M',1.0,nx*1.0,nx*1.0,0.5,'c',1,1,[0,0,0],'XY'); m.meshes['M'].generate()
        for node in list(m.nodes.values()):
            if abs(node.Y)<1e-9: m.def_support(node.name,1,1,1,1,1,1)
        return m
    return f
add('plate mesh 20x20 fixed edge', s_plate_fixed(20), 'STABLE')

def s_thin_plate():
    m=mk(); m.add_material('c',3600,1500,0.2,0.0868)
    m.add_rectangle_mesh('M',0.5,20,20,0.05,'c',1,1,[0,0,0],'XY'); m.meshes['M'].generate()
    for node in list(m.nodes.values()):
        if abs(node.Y)<1e-9 or abs(node.Y-20)<1e-9: m.def_support(node.name,1,1,1,1,1,1)
    return m
add('thin plate t=0.05 mesh', s_thin_plate, 'STABLE')

def s_mixed_stiffness():
    # rigid link (E huge) + normal frame
    m=FEModel3D()
    m.add_material('steel',29000,11200,0.3,0.284); m.add_material('rigid',29000*1e6,11200*1e6,0.3,0.284)
    m.add_section('S',10,100,150,250); m.add_section('R',100,10000,10000,10000)
    m.add_node('a',0,0,0); m.add_node('b',10,0,0); m.add_node('c',10.2,0,0); m.add_node('d',20,0,0)
    m.add_member('m1','a','b','steel','S'); m.add_member('rl','b','c','rigid','R'); m.add_member('m2','c','d','steel','S')
    m.def_support('a',1,1,1,1,1,1); m.def_support('d',0,1,1,0,0,0)
    return m
add('rigid-link mixed stiffness', s_mixed_stiffness, 'STABLE')

def s_spring_supported():
    m=mk(); m.add_node('a',0,0,0); m.add_node('b',10,0,0); m.add_member('m','a','b','steel','S')
    m.def_support('a',0,0,0,1,1,1)
    for d in ('DX','DY','DZ'): m.def_support_spring('a',d,1e-4)
    m.def_support('b',0,1,1,0,0,0); return m
add('soft spring 1e-4 support', s_spring_supported, 'STABLE')

def s_soft6():
    m=mk(); m.add_node('a',0,0,0); m.add_node('b',10,0,0); m.add_member('m','a','b','steel','S')
    m.def_support('b',0,1,1,0,0,0)
    for d in ('DX','DY','DZ'): m.def_support_spring('a',d,1e-6)
    for d in ('RX','RY','RZ'): m.def_support_spring('a',d,1e-4)
    return m
add('soft spring 1e-6 (all dofs)', s_soft6, 'STABLE')

def s_grid():
    m=mk(); nx,ny=8,8
    for i in range(nx+1):
        for j in range(ny+1): m.add_node(f'n{i}_{j}', i*10.0, 0, j*10.0)
    k=0
    for i in range(nx+1):
        for j in range(ny+1):
            if i<nx: m.add_member(f'b{k}', f'n{i}_{j}', f'n{i+1}_{j}','steel','S'); k+=1
            if j<ny: m.add_member(f'b{k}', f'n{i}_{j}', f'n{i}_{j+1}','steel','S'); k+=1
    for i in range(nx+1):
        m.def_support(f'n{i}_0',1,1,1,1,1,1)
    return m
add('8x8 grillage', s_grid, 'STABLE')

for name, fn, expect in models:
    try:
        report(name, fn(), expect)
    except Exception as e:
        print(f'{expect:8s} {name:42s} ERROR {type(e).__name__}: {e}')
