"""Dump full-precision results for a battery of stable models."""
import sys, json, io, contextlib
import numpy as np
sys.path.insert(0, '/workspace/task/source')
from Pynite import FEModel3D

def mk():
    m = FEModel3D(); m.add_material('steel',29000,11200,0.3,0.284)
    m.add_section('S',10,100,150,250); return m

def control():
    m = mk(); m.add_node('n1',0,0,0); m.add_node('n2',10,0,0)
    m.add_member('m','n1','n2','steel','S')
    m.def_support('n1',1,1,1,1,1,1); m.def_support('n2',0,1,1,0,0,0)
    m.add_member_dist_load('m','Fy',-1,-1); return m

def frame3d():
    m = mk()
    for k,(x,y,z) in {'n1':(0,0,0),'n2':(4,3,1),'n3':(8,0,2),'n4':(4,-3,5)}.items(): m.add_node(k,x,y,z)
    for nm,(i,j) in {'a':('n1','n2'),'b':('n2','n3'),'c':('n3','n4'),'d':('n4','n1'),'e':('n1','n3')}.items():
        m.add_member(nm,i,j,'steel','S')
    m.def_support('n1',1,1,1,1,1,1); m.def_support('n3',1,1,1,0,0,0)
    m.add_node_load('n2','FY',-3); m.add_node_load('n4','FZ',2)
    m.add_member_dist_load('b','FY',-1,-1)
    m.add_load_combo('C2', {'Case 1': 1.6})
    return m

def chain(N=40):
    m = mk()
    for i in range(N+1): m.add_node(f'n{i}', i*1.0, 0, 0)
    for i in range(N): m.add_member(f'm{i}', f'n{i}', f'n{i+1}','steel','S')
    m.def_support('n0',1,1,1,1,1,1)
    m.add_node_load(f'n{N}','FY',-2)
    for i in range(N): m.add_member_dist_load(f'm{i}','Fy',-0.5,-0.5)
    return m

def springs():
    m = mk(); m.add_node('a',0,0,0); m.add_node('b',10,0,0); m.add_node('c',20,0,0)
    m.add_member('m1','a','b','steel','S'); m.add_member('m2','b','c','steel','S')
    m.def_support('a',1,1,1,1,1,1)
    m.def_support_spring('c','DY',100)
    m.add_spring('s','b','c',50)
    m.add_node_load('b','FY',-5)
    m.def_support('c',0,0,1,0,0,0)
    return m

def plate_mesh():
    m = mk(); m.add_material('c',3600,1500,0.2,0.0868)
    m.add_rectangle_mesh('M',1.0,6,6,0.5,'c',1,1,[0,0,0],'XY'); m.meshes['M'].generate()
    for node in list(m.nodes.values()):
        if abs(node.Y) < 1e-9: m.def_support(node.name,1,1,1,1,1,1)
    for node in list(m.nodes.values()):
        if abs(node.Y-6) < 1e-9: m.add_node_load(node.name,'FZ',-0.5)
    return m

def tc_model():
    m = mk(); m.add_node('a',0,0,0); m.add_node('b',10,0,0); m.add_node('c',10,10,0); m.add_node('d',0,10,0)
    for nm,(i,j) in {'col1':('a','d'),'beam':('d','c'),'col2':('b','c')}.items(): m.add_member(nm,i,j,'steel','S')
    m.add_member('brace','a','c','steel','S', tension_only=True)
    m.def_support('a',1,1,1,1,1,1); m.def_support('b',1,1,1,1,1,1)
    m.def_support('c',0,0,1,1,1,0); m.def_support('d',0,0,1,1,1,0)
    m.add_node_load('d','FX',10)
    return m

def enforced():
    m = mk(); m.add_node('a',0,0,0); m.add_node('b',10,0,0)
    m.add_member('m','a','b','steel','S')
    m.def_support('a',1,1,1,1,1,1); m.def_support('b',0,0,1,1,1,0)
    m.def_node_disp('b','DY',-0.5)
    m.add_node_load('b','FX',-2)
    return m

def pdelta_model():
    m = mk(); N=6
    for i in range(N+1): m.add_node(f'n{i}',0,i*2.0,0)
    for i in range(N): m.add_member(f'm{i}',f'n{i}',f'n{i+1}','steel','S')
    m.def_support('n0',1,1,1,1,1,1)
    m.add_node_load(f'n{N}','FY',-30, case='Case 1')
    m.add_node_load(f'n{N}','FX',1, case='Case 1')
    return m

def collect(model, combos):
    out = {}
    for name, node in model.nodes.items():
        for combo in combos:
            for attr in ('DX','DY','DZ','RX','RY','RZ','RxnFX','RxnFY','RxnFZ','RxnMX','RxnMY','RxnMZ'):
                d = getattr(node, attr)
                if combo in d: out[f'{name}.{attr}.{combo}'] = repr(float(d[combo]))
    for name, pm in model.members.items():
        for combo in combos:
            try:
                out[f'{name}.maxM.{combo}'] = repr(float(pm.max_moment('Mz', combo)))
                out[f'{name}.axial.{combo}'] = repr(float(pm.max_axial(combo)))
                out[f'{name}.maxdefl.{combo}'] = repr(float(pm.max_deflection('dy', combo)))
            except Exception as e:
                out[f'{name}.err.{combo}'] = type(e).__name__
    return out

results = {}
cases = [('control', control), ('frame3d', frame3d), ('chain', chain), ('springs', springs),
         ('plate_mesh', plate_mesh), ('tc_model', tc_model), ('enforced', enforced)]
for label, factory in cases:
    for sparse in (True, False):
        for method in ('analyze', 'analyze_linear'):
            key = f'{label}|{method}|{"sparse" if sparse else "dense"}'
            try:
                m = factory()
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    getattr(m, method)(sparse=sparse, check_statics=True)
                results[key] = collect(m, list(m.load_combos.keys()))
                results[key]['__statics__'] = buf.getvalue().replace('\n',' | ')
            except Exception as exc:
                results[key] = {'__error__': f'{type(exc).__name__}: {exc}'}

for sparse in (True, False):
    key = f'pdelta|{"sparse" if sparse else "dense"}'
    try:
        m = pdelta_model()
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            m.analyze_PDelta(sparse=sparse)
        results[key] = collect(m, list(m.load_combos.keys()))
    except Exception as exc:
