def run(model, method='analyze', **kw):
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        getattr(model, method)(**kw)
    return buf.getvalue()

def probe(model):
    """Returns a signature of the response for comparison between modes."""
    out = []
    for name, node in model.nodes.items():
        for attr in ('DX','DY','DZ','RX','RY','RZ','RxnFX','RxnFY','RxnFZ','RxnMX','RxnMY','RxnMZ'):
            d = getattr(node, attr)
            for combo, value in d.items(): out.append(float(value))
    return np.array(out)

def rel(a, b):
    denom = np.maximum(np.maximum(np.abs(a), np.abs(b)), 1e-9)
    return float(np.max(np.abs(a-b)/denom)) if a.size else 0.0

