for label, factory in STABLE:
    sigs = {}
    problems = []
    for method in ('analyze','analyze_linear'):
        for sparse in (True, False):
            for opt in options:
                if method == 'analyze_linear' and 'num_steps' in opt: continue
                kw = dict(opt); kw['sparse'] = sparse
                try:
                    m = factory(); run(m, method, **kw)
                    sig = probe(m)
                    if not np.all(np.isfinite(sig)): problems.append(f'{method}/{sparse}/{opt}: non-finite')
                    sigs[f'{method}|{sparse}|{json.dumps(opt,sort_keys=True)}'] = sig
                except Exception as exc:
                    problems.append(f'{method}/{"sp" if sparse else "de"}/{opt}: {type(exc).__name__}: {exc}')
    if sigs:
        base = next(iter(sigs.values()))
        spread = max(rel(base, s) for s in sigs.values())
    else:
        spread = float('nan')
    status = 'OK  ' if not problems and spread < 1e-6 else 'FAIL'
    if status == 'FAIL': fail += 1
    print(f'{status} {label:22s} spread={spread:.2e} {"; ".join(problems[:2])}')

print()
print('=== unstable models: must be reported, in every mode/option ===')
for label, factory in UNSTABLE:
    outcomes = {}
