                key = f'{method}|{"sp" if sparse else "de"}|{json.dumps(opt,sort_keys=True)}'
                try:
                    m = factory(); run(m, method, **kw)
                    outcomes[key] = 'SOLVED(!)'
                except Exception as exc:
                    outcomes[key] = type(exc).__name__
    reported = all(v != 'SOLVED(!)' for v in outcomes.values())
    types = sorted(set(outcomes.values()))
    status = 'OK  ' if reported else 'FAIL'
    if not reported: fail += 1
    bad = [k for k,v in outcomes.items() if v == 'SOLVED(!)']
    print(f'{status} {label:22s} outcomes={types} {("solved in: "+str(bad[:3])) if bad else ""}')

print()
