    tree=ast.parse(open(path).read())
    imported=set()
    for node in ast.walk(tree):
        if isinstance(node,(ast.Import,ast.ImportFrom)):
            for a in node.names:
                imported.add((a.asname or a.name).split('.')[0])
    used={n.id for n in ast.walk(tree) if isinstance(n,ast.Name)} | {n.attr for n in ast.walk(tree) if isinstance(n,ast.Attribute)}
    src=open(path).read()
    unused=[i for i in sorted(imported) if i not in used and src.count(i)<3]
    print(path,'possibly unused imports:',unused)
